import sys
import json

MOD = 1_000_000_007

def mod_pow(base, exp, mod):
    result = 1
    while exp:
        if exp & 1:
            result = result * base % mod
        base = base * base % mod
        exp >>= 1
    return result

class Solution:
    def maxNiceDivisors(self, primeFactors: int) -> int:
        if primeFactors <= 3:
            return primeFactors
        r = primeFactors % 3
        if r == 0:
            return mod_pow(3, primeFactors // 3, MOD)
        if r == 1:
            return 4 * mod_pow(3, (primeFactors - 4) // 3, MOD) % MOD
        return 2 * mod_pow(3, (primeFactors - 2) // 3, MOD) % MOD

