const readline = require('readline');
const MOD = 1000000007n;

function modPow(base, exp) {
    base = BigInt(base) % MOD;
    exp = BigInt(exp);
    let result = 1n;
    while (exp > 0n) {
        if (exp & 1n) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1n;
    }
    return result;
}

var maxNiceDivisors = function(primeFactors) {
    const n = BigInt(primeFactors);
    if (n <= 3n) return Number(n);
    const r = n % 3n;
    let ans;
    if (r === 0n) ans = modPow(3n, n / 3n);
    else if (r === 1n) ans = 4n * modPow(3n, (n - 4n) / 3n) % MOD;
    else ans = 2n * modPow(3n, (n - 2n) / 3n) % MOD;
    return Number(ans);
};

